constexpr s32 kCamFlags = 4;         // u32: bit 31 shows the debug cylinder
constexpr s32 kCamMode = 8;          // s32: 0 / 5 ride on the pivot, 2 aim at the pivot, 3 rail, 4 rail points, 1 none
constexpr s32 kCamPivot = 12;        // RwFrame*: the pivot frame
constexpr s32 kCamParent = 16;       // RwFrame*: the main camera frame's parent at creation
constexpr s32 kCamOffset = 20;       // f32[3]: added to the target position
constexpr s32 kCamRadius = 32;       // f32: the dead zone's radius (horizontal)
constexpr s32 kCamHeight = 36;       // f32: the dead zone's height (vertical slack = height / 2)
constexpr s32 kCamRailTask = 64;     // KwlnTask*: destroyed when the mode leaves the rail (never created here)
constexpr s32 kCamRailMark0 = 68;    // KwlnTask*: three rail debug points (sub_1A46F0): the camera's sample,
constexpr s32 kCamRailMark1 = 72;    //   the rail point before the nearest one,
constexpr s32 kCamRailMark2 = 76;    //   and the one after it
constexpr s32 kCamRailPoints = 96;   // f32[9][3]: the rail sampled at t = i / 8 (sub_1D5C10)
constexpr s32 kCamTarget = 204;      // the target scene resource (sub_1D5F30); 0 = the update does nothing

// --- the main camera, RW frames, scene data -----------------------------------------------------------------------
constexpr s32 kMainCamFrame = 4;     // the main camera object (sub_198590) +4: its RwFrame
constexpr s32 kFrameParent = 4;      // RwFrame +4: the parent frame
constexpr s32 kFrameMatrix = 16;     // RwFrame +16: the modelling matrix (64 bytes)
constexpr s32 kFramePos = 64;        // RwFrame +64: the modelling matrix's position row
constexpr s32 kResController = 480;  // scene resource +480: its collision controller task (sub_1AD940 reads it)
constexpr s32 kFieldCamera = 4;      // sField +4: the camera controller task
constexpr s32 kFieldCollision = 4460;  // sField +4460: the field's collision record
constexpr s32 kCollRail = 2588;      // collision record +2588: the camera rail spline (0 = none)

