constexpr s32 kRotFrames = 4;        // s32: the duration in frames
constexpr s32 kRotFrame = 8;         // s32: frames done
constexpr s32 kRotFirst = 12;        // f32: the first frame's turn (0: never set by the creators)
constexpr s32 kRotTotal = 16;        // f32: the whole turn in degrees (the shorter way round)
