                            charge(ctx, 17);
                            jal(ctx, 0x1D5358u, gen::fn_sub_198590_00198590);
                            lw(a0, v0, kMainCamFrame);
                            jal(ctx, 0x1D5364u, gen::fn_sub_4CB590_004cb590);
                            lw(a0, s2, kCamParent);
                            lw(a1, s2, kCamPivot);
                            jal(ctx, 0x1D5374u, gen::fn_sub_4CB420_004cb420);
                            jal(ctx, 0x1D537Cu, gen::fn_sub_198590_00198590);
                            lw(a0, s2, kCamPivot);
