                        swc1(f2, sp, 0x130);
                        lwc1(f1, s2, kCamOffset + 4);
                        lwc1(f0, sp, 0x134);
                        add_s(f3, f0, f1);
                        swc1(f3, sp, 0x134);
                        lwc1(f1, s2, kCamOffset + 8);
