                            a1 = a0;
                            jal(ctx, 0x1D5480u, gen::fn_sub_4C69F0_004c69f0);
                            lwc1(f0, sp, 0x110);
                            mul_s(f0, f0, f21);
                            swc1(f0, sp, 0x110);
                            lwc1(f0, sp, 0x114);
                            mul_s(f0, f0, f21);
